from pathlib import Path
import pandas as pd,numpy as np,json,xml.etree.ElementTree as E
ROOT=Path(__file__).resolve().parents[1]
ORDER=['baseline','capacity','stagger','combined','adaptive'];LABEL=['Baseline','Capacity','Stagger','Combined','Adaptive'];COL=['#333333','#E64B35','#4DBBD5','#00A087','#3C5488']
def main():
    a=pd.read_csv(ROOT/'analysis/summary_by_run.csv');g=a.groupby('scenario').mean(numeric_only=True)
    def val(s,k):return float(g.loc[s,k])
    def read(s,k):return pd.read_csv(ROOT/'analysis'/f'{s}_s4711_{k}.csv.gz')
    def curve(s,k,x,y):
        d=read(s,k);return {'name':LABEL[ORDER.index(s)],'x':d[x].tolist(),'y':d[y].tolist(),'color':COL[ORDER.index(s)]}
    slides=[]
    def add(title,seconds,body=None,chart=None,table=None,notes='',foot=''):
        slides.append(dict(title=title,seconds=seconds,body=body,chart=chart,table=table,notes=notes,foot=foot))
    add('Capacity and departure scheduling\nin MATSim',30,['LSGI3213 Intelligent Transportation Systems','A reproducible experiment with the official equil network','15-minute presentation'],notes='This project examines two ways of reducing congestion: changing road discharge capacity and changing when people depart. We use the official equil example and execute the scenarios in MATSim 12.0. Our evidence includes actual event files, repeated runs and comparisons of trips, daily plan scores and link states. The network and population are synthetic, so the findings describe this experiment rather than a forecast for Hong Kong.')
    add('Research questions',55,['What changes when bottleneck capacity doubles?','What changes when the same travellers leave across one hour?','Do capacity and scheduling provide overlapping benefits?','How does learned departure timing differ from an assigned schedule?'],notes='The number of travellers does not determine congestion on its own. When they depart and how they distribute themselves over routes matter as well. We first separate a supply intervention from a timing intervention. We then combine them to see whether their benefits overlap. Finally, we let agents change departure times through a configuration change. That distinction matters: an imposed schedule represents coordination, whereas adaptive timing represents individual responses to the model scoring rules. We assess both traffic performance and daily scores, since improving one does not necessarily improve the other by the same amount.')
    net=E.parse(ROOT/'data/raw/network.xml').getroot();nodes={n.get('id'):[float(n.get('x'))/1000,float(n.get('y'))/1000] for n in net.findall('./nodes/node')};edges=[]
    for l in net.findall('./links/link'):
        xy=[nodes[l.get('from')],nodes[l.get('to')]];edges.append(dict(name=l.get('id'),x=[p[0] for p in xy],y=[p[1] for p in xy],color=COL[1] if 11<=int(l.get('id'))<=19 else '#8796A0'))
    add('Official equil data',65,['15 nodes; 23 directed links','2,000 agents: home-work-home','Nine outward corridors; shared return path','Downloaded inputs match the tutorial files byte for byte'],chart=dict(type='network',series=edges,xlabel='Synthetic x (km)',ylabel='Synthetic y (km)'),notes='The assignment permits equil or chessboard. We selected equil and downloaded the version-tagged inputs from the official MATSim repository. Five downloaded files match the corresponding tutorial files byte for byte. The Blackboard project ZIP itself was not accessed, so we distinguish those two claims. The network has nine outward alternatives and a shared return path. Red lines represent links eleven to nineteen, which receive the capacity treatment. Coordinates are synthetic and road lengths are read from XML, not measured from this drawing. The principal experiment uses the supplied two-thousand-person population with four thousand daily car trips.',foot='Source: MATSim matsim-12.0 equil example; public repository and SHA-256 manifest included')
    add('MATSim execution and learning',60,['Select a remembered daily plan','Execute all agents together in QSim','Score activities, travel and timing','ReRoute explores alternatives; BestScore selects remembered plans'],notes='MATSim executes individual activity plans together, so the congestion experienced by one agent depends on everyone else. The mobility simulation is queue based. Vehicles require a free-speed traversal time and then face discharge and downstream constraints. After execution, daily activity and travel experiences generate scores. In the fixed-time scenarios, BestScore has weight zero point nine and ReRoute has weight zero point one, with a five-plan memory limit. We repeat this process through iteration one hundred. The resulting mean score is informative about learning, but a flat line alone is not proof of exact network equilibrium.',foot='Sources: MATSim Book; MATSim 12.0 configuration and Java source')
    add('Five controlled scenarios',85,table=[['Scenario','Supply / schedule','Replanning'],['Baseline','All first departures at 06:00','BestScore 0.9; ReRoute 0.1'],['Capacity','Links 11-19: 1,000 → 2,000 veh/h','Same'],['Stagger','Departures spread 05:30-06:30','Same'],['Combined','Capacity + Stagger','Same'],['Adaptive','Baseline initial network and plans','0.1 time mutation; BestScore 0.8']],notes='Every main scenario keeps two thousand agents, the same home and work links, car mode and an eight-hour work activity. Capacity doubles discharge capacity on nine corridor links, without adding lanes or increasing free speed. Stagger assigns equally spaced departure times between five thirty and six thirty, preserving a six o’clock mean. Combined applies both changes. Adaptive starts with the baseline inputs but reallocates one tenth of the BestScore weight to TimeAllocationMutator. Its mutation range is thirty minutes and it does not mutate the explicit work duration. Repeated mutations can accumulate, so the final adaptive departure distribution is not restricted to the externally staggered window.',foot='Common controls: scoring, demand, facilities, free speed, lanes, iterations and seed set')
    add('Execution and independent checks',45,['15 main runs: 5 scenarios × 3 seeds','Iterations 0-100; seeds 4711, 42 and 2025','4,000 completed trips per main run; zero stuck agents','Event-based trip times agree with MATSim native trip tables'],notes='The main experiment contains fifteen runs. Seeds are paired across scenarios, and all runs use single-thread settings to reduce unnecessary execution variability. Each final main run completes exactly four thousand trips with no stuck agents or unmatched departure and arrival events. We independently reconstruct trip durations from events and match them to every native trip-table row. Selected-plan scores are also checked against the executed-score history. The original one-hundred-person example is run separately as a reproduction check. Its different schedule structure means it is not the denominator for the policy comparisons.',foot='MATSim 12.0; Java 11.0.30; saved XML, event files, logs and validation code')
    series=[dict(name='Mean morning time',y=[val(s,'am_mean_min') for s in ORDER],color=COL[4])]
    add('Morning travel time',85,chart=dict(type='bar',categories=LABEL,series=series,ylabel='Mean morning travel time (min)',max=25),notes=f'The baseline morning trip takes {val("baseline","am_mean_min"):.2f} minutes on average across the three seeds. Capacity reduces that to {val("capacity","am_mean_min"):.2f} minutes. Staggering reduces it to {val("stagger","am_mean_min"):.2f}, and the combination to {val("combined","am_mean_min"):.2f}. The adaptive scenario gives {val("adaptive","am_mean_min"):.2f} minutes. Trip numbers remain fixed, so these improvements come from travel experience rather than cancelling journeys. Notice the small difference between Stagger and Combined: once the departure pulse has been spread enough to remove most queues, extra capacity has little remaining delay to remove. The report also gives the ninety-fifth percentile and total daily travel hours.',foot='Mean of three final-iteration runs; 2,000 morning trips per run; bar axis starts at zero')
    series=[]
    for s in ['baseline','stagger','adaptive']:
        t=read(s,'trips').query('trip_number==1');bins=np.arange(4.5*3600,9*3600+900,900);n,b=np.histogram(t.departure_s,bins)
        series.append(dict(name=LABEL[ORDER.index(s)],x=(b[:-1]/3600).tolist(),y=n.tolist(),color=COL[ORDER.index(s)]))
    add('Realised departure patterns',60,chart=dict(type='scatter',series=series,xlabel='Hour of day',ylabel='Departures per 15 min',minx=4.5,maxx=9,miny=0),notes='This figure uses the first trip of every person at seed forty-seven eleven. Baseline departures form a pulse around six. The staggered intervention spreads that pulse symmetrically, whereas adaptive timing emerges from learning. Capacity alone does not change the first planned departure times. The adaptive pattern is affected by the work opening time of seven and the penalties and rewards in the daily scoring system. These are realised departure events, not counts of vehicles already admitted to a full road link. The report also uses five-minute bins to show whether a coarser histogram conceals a short concentration.',foot='Seed 4711; matching 5-minute histogram is supplied in the report and figure data')
    series=[]
    for s in ORDER:
        x=np.sort(read(s,'trips').query('trip_number==1').travel_s.to_numpy()/60);idx=np.linspace(0,len(x)-1,201).astype(int)
        series.append(dict(name=LABEL[ORDER.index(s)],x=x[idx].tolist(),y=((idx+1)/len(x)).tolist(),color=COL[ORDER.index(s)]))
    add('Travel-time distributions',55,chart=dict(type='scatter',series=series,xlabel='Morning travel time (min)',ylabel='Cumulative share',minx=14,maxx=35,miny=0,maxy=1),notes='The cumulative distribution adds information hidden by an average. At a given travel time, the vertical position shows the share of morning trips completed within that duration. A curve further left generally indicates shorter trips. A near-vertical curve means that many agents experience almost the same duration. The displayed curves use two hundred and one ordered points from each two-thousand-trip distribution for clarity, while the full observations remain in the result files. Differences near the upper end identify the slower travellers, and the report pairs individual agents to examine who gains or loses.',foot='Seed 4711; 2,000 morning trips per scenario; ordered points sampled for display')
    series=[curve(s,'score_history','ITERATION','avg. EXECUTED') for s in ORDER]
    add('Executed scores and timing preferences',80,chart=dict(type='scatter',series=series,xlabel='Iteration',ylabel='Executed score (utils)',minx=0,maxx=100,miny=118,maxy=132),notes=f'At iteration one hundred, average executed scores across seeds are {val("baseline","mean_score"):.2f} in Baseline and {val("adaptive","mean_score"):.2f} in Adaptive. The adaptive line improves more strongly because changing departure times affects activity timing as well as travel. Work opens at seven, has a latest start time of nine and closes at eighteen. Arriving early can therefore interact with the activity utility even if the trip is quick. These model-specific utility scores are not money and should not be converted into monetary benefits without a defensible welfare model. The report includes all three seed histories and a magnified late-iteration panel, and we extend selected runs to test remaining drift.',foot='Seed 4711 shown; identical scoring rules; three-seed histories and extended runs in report')
    series=[]
    for s in ORDER:
        t=read(s,'traversals');t=t[t.link.between(11,19)];v=(t.assign(delay=(t.travel_s-5000/27.78).clip(lower=0)/60).groupby('link').delay.mean().reindex(range(11,20)))
        v=v.dropna();series.append(dict(name=LABEL[ORDER.index(s)],x=v.index.tolist(),y=v.tolist(),color=COL[ORDER.index(s)]))
    add('Delay on the nine corridor links',85,chart=dict(type='scatter',series=series,xlabel='Link ID',ylabel='Mean full-link delay (min)',minx=11,maxx=19,miny=0,maxy=10),notes='The network-wide travel comparison has a physical mechanism. This plot subtracts nominal free-speed time from full-link traversal time for each treated corridor link. The recorded traversal starts with entered-link and ends with left-link for the same vehicle. We exclude activity endpoint links from full-link speed interpretation because their traversal can be partial. The report also calculates exit flow, exact time-averaged occupancy and density. Occupancy includes moving vehicles, so it must not be called queue length. Throughput can temporarily rise as queues clear even while travel time improves. We use both fifteen-minute and five-minute bins, and leave empty traversal bins missing rather than filling them with zero.',foot='Seed 4711; delay = max(traversal time − length/free speed, 0); endpoint links excluded')
    sens=json.loads((ROOT/'analysis/sensitivity.json').read_text());text='; '.join(f'{x["scenario"]}: {x["original_am_mean_min"]:.2f} → {x["am_mean_min"]:.2f} min' for x in sens)
    rows=[['Scenario','AM mean: three-seed range','Tail score change']]
    for s in ORDER:
        r=a[a.scenario==s];rows.append([LABEL[ORDER.index(s)],f'{r.am_mean_min.min():.3f} - {r.am_mean_min.max():.3f} min',f'{r.score_tail_change.mean():+.4f} utils'])
    add('Robustness and convergence limits',65,table=rows,notes='The three-seed range indicates numerical variability under these settings. It is not a confidence interval for a real population. Tail score change compares the last ten iterations with the preceding ten. A small change supports stability of that average, while continued drift, particularly in Adaptive, makes the horizon important. We also reran the baseline and adaptive cases with two hundred iterations from the same starting inputs. The extended morning-time results are '+text+'. Longer runs can reveal continuing learning, but they cannot validate synthetic demand or the assumed schedule preferences. More observed data are needed for that.',foot='Tail change: mean score at iterations 91-100 minus 81-90; 200-iteration checks in report')
    inter=val('combined','am_mean_min')-val('capacity','am_mean_min')-val('stagger','am_mean_min')+val('baseline','am_mean_min')
    add('Interpretation for ITS',55,[f'Capacity and scheduling overlap: interaction = {inter:+.2f} min','Staggering assumes full participation and flexible schedules','Capacity change raises discharge flow; it does not add lanes','Stagger / Combined: 41.2-41.6% have lower daily scores'],notes='Both interventions address the same queueing process, which explains why their benefits need not add. Across the three seeds, between 41.2 and 41.6 percent of agents have a lower daily score under Stagger and Combined, despite the higher mean score. This supports the warning about schedule inconvenience. The factorial interaction is Combined minus Capacity minus Stagger plus Baseline. A positive value means the joint saving is smaller than the sum of the separate savings. This is a controlled simulation comparison, not a causal estimate for an observed city. An actual ITS programme would need employer coordination or traveller incentives, measured participation and schedule constraints. Expansion would need engineering and cost assessment. The simulation provides traffic evidence but cannot establish which intervention is cost-effective, safest or most equitable.')
    add('Conclusions',55,[f'Baseline morning duration: {val("baseline","am_mean_min"):.2f} min',f'Capacity saving: {100*(1-val("capacity","am_mean_min")/val("baseline","am_mean_min")):.1f}%; Stagger saving: {100*(1-val("stagger","am_mean_min")/val("baseline","am_mean_min")):.1f}%',f'Combined duration: {val("combined","am_mean_min"):.2f} min; extra capacity adds little once queues are removed','Interpret travel, daily scores and link states together'],notes='The key result is that the same four thousand daily trips can produce different congestion when supply or timing changes. Capacity reduces the morning queue, while spreading departures removes much of its formation in this synthetic example. Combining them gives limited extra benefit after delays are nearly removed. Adaptive timing illustrates the importance of activity preferences and continuing learning. The project therefore satisfies the three requested analysis dimensions: trips, daily plan scores and link states. The complete inputs, code, logs and events are supplied so that another person can reproduce the analysis and examine assumptions rather than relying only on the presentation.')
    add('Sources and acknowledgment',20,['MATSim developers: official equil inputs, matsim-12.0 tag','Horni, Nagel & Axhausen (2016), The Multi-Agent Transport Simulation MATSim','OpenAI Codex assisted with data discovery, code, execution, analysis, report and slides','Full references, source hashes and AI disclosure accompany the report'],notes='Full references and file hashes are included in the report and project package. AI assistance covered design, implementation, analysis and writing and is disclosed explicitly. The numerical evidence comes from the saved MATSim runs. Thank you; we welcome questions about the assumptions, methods and results.',foot='github.com/matsim-org/matsim-libs  |  doi.org/10.5334/baw')
    assert sum(s['seconds'] for s in slides)==900
    (ROOT/'analysis/slides_content.json').write_text(json.dumps(slides,indent=2,allow_nan=False))
    notes=['# 15-minute presentation script\n','English slides and script; timing includes pointing to figures and short pauses.\n']
    t=0
    for i,s in enumerate(slides,1):
        notes.append(f'## Slide {i}: {s["title"].replace(chr(10)," ")} ({t//60:02d}:{t%60:02d}-{(t+s["seconds"])//60:02d}:{(t+s["seconds"])%60:02d})\n\n{s["notes"]}\n');t+=s['seconds']
    notes.append('## 中文答辩提示\n\n- 为什么不用真实香港数据？题目指定 equil/chessboard；这里选择官方 equil。它是机制实验，不是城市预测。\n- 为什么 100 人和 2,000 人得分差很多？计划结构与工作时长不同，不能直接归因于人口规模；干预比较只在相同的 2,000 人需求之间进行。\n- 为什么错峰之后扩容帮助很小？两种措施消除的是相同队列，错峰已接近无拥堵基准，存在收益重叠。\n- 得分是否等于福利或钱？不是；它还受活动时长、到达时刻和工作开放时间影响。\n- 为什么不是加车道？本实验只改 capacity，车道与长度保持不变，因此是放行能力实验。\n- 是否已经收敛？查看末段得分变化与 200 次扩展运行；特别是自适应时间场景仍可能继续学习，不能声称精确均衡。\n- 是否验证过数据？五个官方文件与教程一致；事件出行时间与原生 trip 表逐行匹配，全部完成且无 stuck。\n- 能否直接用于政策？还需真实需求校准、参与率、成本、排放与公平性分析。\n')
    (ROOT/'deliverables/Presentation_Script_and_QA.md').write_text('\n'.join(notes))
    print('15 slides; timing exactly 900 seconds')
if __name__=='__main__':main()
